from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError("Wrong number of fields")

    def parse_field(field_str, min_val, max_val):
        values = set()
        parts = field_str.split(',')
        for part in parts:
            if not part:
                raise ValueError("Empty item")
            step = 1
            if '/' in part:
                base, step_str = part.split('/', 1)
                if not step_str.isdigit() or int(step_str) < 1:
                    raise ValueError("Invalid step")
                step = int(step_str)
            else:
                base = part

            if base == '*':
                start, end = min_val, max_val
            elif '-' in base:
                range_parts = base.split('-', 1)
                if not range_parts[0].isdigit() or not range_parts[1].isdigit():
                    raise ValueError("Invalid range")
                start, end = int(range_parts[0]), int(range_parts[1])
                if start > end:
                    raise ValueError("A > B")
                if not (min_val <= start <= max_val and min_val <= end <= max_val):
                    raise ValueError("Out of range")
            elif base.isdigit():
                start = int(base)
                end = max_val
                if not (min_val <= start <= max_val):
                    raise ValueError("Out of range")
            else:
                raise ValueError("Invalid character")

            for v in range(start, end + 1, step):
                values.add(v)
        return sorted(values)

    minutes = parse_field(fields[0], 0, 59)
    hours = parse_field(fields[1], 0, 23)
    doms = parse_field(fields[2], 1, 31)
    months = parse_field(fields[3], 1, 12)
    dows = parse_field(fields[4], 0, 7)
    # Normalize 7 to 0 for day-of-week
    dows = [0 if d == 7 else d for d in dows]

    dom_restricted = (fields[2] != '*')
    dow_restricted = (fields[4] != '*')

    # Start strictly after `after`, rounded down to minute, then add 1 minute
    current = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=3000)

    while current <= limit:
        if current.month not in months:
            # Jump to next month
            if current.month == 12:
                current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
            continue

        # Day matching logic
        dom_match = current.day in doms
        # Python weekday: 0=Monday, 6=Sunday. Cron dow: 1=Monday...6=Saturday, 0/7=Sunday
        # Map cron dow to python: (cron_dow % 7) == (current.weekday() + 1) % 7
        dow_match = any((d % 7) == (current.weekday() + 1) % 7 for d in dows)

        if dom_restricted and dow_restricted:
            day_match = dom_match or dow_match
        else:
            day_match = dom_match and dow_match

        if not day_match:
            current = current.replace(hour=0, minute=0) + timedelta(days=1)
            continue

        if current.hour not in hours:
            # Find next valid hour in current day
            next_h = None
            for h in hours:
                if h > current.hour:
                    next_h = h
                    break
            if next_h is not None:
                current = current.replace(hour=next_h, minute=0)
            else:
                current = current.replace(hour=0, minute=0) + timedelta(days=1)
            continue

        if current.minute not in minutes:
            # Find next valid minute in current hour
            next_m = None
            for m in minutes:
                if m > current.minute:
                    next_m = m
                    break
            if next_m is not None:
                current = current.replace(minute=next_m)
            else:
                current = current.replace(hour=0, minute=0) + timedelta(days=1)
            continue

        return current

    raise ValueError("No match within 3000 days")
