                        i += 3
                    else:
                        chars.add(seg[i])
                        i += 1
                if i >= n:
                    raise ValueError("Unterminated [")
                i += 1  # skip ']'
                tokens.append(('set', chars, negated))
            elif ch == '\\' and i + 1 < n:
                tokens.append(('literal', seg[i+1]))
                i += 2
            else:
                tokens.append(('literal', ch))
                i += 1

        # Compile tokens to a fast matcher
        def match_segment(text):
            t_len = len(text)
            memo = {}

            def dp(ti, pi):
                state = (ti, pi)
                if state in memo:
                    return memo[state]

                if pi == len(tokens):
                    res = ti == t_len
                    memo[state] = res
                    return res

                tok = tokens[pi]
                if tok[0] == 'literal':
                    if ti < t_len and text[ti] == tok[1]:
                        res = dp(ti + 1, pi + 1)
                    else:
                        res = False
                elif tok[0] == '?':
                    if ti < t_len and text[ti] != '/':
                        res = dp(ti + 1, pi + 1)
                    else:
                        res = False
                elif tok[0] == '*':
