            op = '='
            if token.startswith('>='):
                op = '>='
                v_str = token[2:]
            elif token.startswith('<='):
                op = '<='
                v_str = token[2:]
            elif token.startswith('>'):
                op = '>'
                v_str = token[1:]
            elif token.startswith('<'):
