            elif op == '>':
                if cmp_res <= 0:
                    set_satisfied = False
                    break
            elif op == '>=':
                if cmp_res < 0:
                    set_satisfied = False
                    break
            elif op == '<':
                if cmp_res >= 0:
                    set_satisfied = False
                    break
            elif op == '<=':
                if cmp_res > 0:
                    set_satisfied = False
                    break
            elif op == '^':
