from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    field_ranges = [
        (0, 59),   # minute
        (0, 23),   # hour
        (1, 31),   # day-of-month
        (1, 12),   # month
        (0, 7),    # day-of-week
    ]

    parsed = []
    dom_restricted = False
    dow_restricted = False

    for i, (field_str, (min_val, max_val)) in enumerate(zip(fields, field_ranges)):
        is_wildcard = (field_str == "*")
        if i == 2:
            dom_restricted = not is_wildcard
        if i == 4:
            dow_restricted = not is_wildcard

        values = set()
        for item in field_str.split(","):
            if not item:
                raise ValueError("Empty item in field")

            step = 1
            if "/" in item:
                parts = item.split("/")
                if len(parts) != 2:
                    raise ValueError("Invalid step syntax")
                base, step_str = parts
                try:
                    step = int(step_str)
                except ValueError:
                    raise ValueError("Step must be an integer")
                if step < 1:
                    raise ValueError("Step must be >= 1")
            else:
                base = item

            if base == "*":
                start, end = min_val, max_val
            elif "-" in base:
                range_parts = base.split("-")
                if len(range_parts) != 2:
                    raise ValueError("Invalid range syntax")
                try:
                    start = int(range_parts[0])
                    end = int(range_parts[1])
                except ValueError:
                    raise ValueError("Range bounds must be integers")
                if start > end:
                    raise ValueError("Start must be <= end in range")
            else:
                try:
                    start = int(base)
                except ValueError:
                    raise ValueError("Value must be an integer")
                end = start

            if start < min_val or end > max_val:
                raise ValueError("Value out of range")

            # Adjust end for step to not exceed max_val
            if step > 1:
                # We want values: start, start+step, start+2*step, ... <= end
                # But also <= max_val
                actual_end = min(end, max_val)
                if start > actual_end:
                    continue
                values.update(range(start, actual_end + 1, step))
            else:
                values.update(range(start, end + 1))

        parsed.append(values)

    minutes, hours, doms, months, dows = parsed

    # Normalize day-of-week: cron 0 and 7 are Sunday. Python weekday(): 0=Mon, 6=Sun
    # Map cron dow to python weekday: (dow - 1) % 7
    python_dows = {(d - 1) % 7 for d in dows}

    current = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=3000)

    while current <= limit:
        if (current.minute in minutes and
            current.hour in hours and
            current.month in months):

            dom_match = current.day in doms
            dow_match = current.weekday() in python_dows

            if dom_restricted and dow_restricted:
                if dom_match or dow_match:
                    return current
            else:
                if dom_match and dow_match:
                    return current

        current += timedelta(minutes=1)

    raise ValueError("No match found within 3000 days")
