        elif op == "remove":
            if not path_tokens:
                raise PatchError("Cannot remove root document")
            parent, key = _get_parent_and_target(result, path_tokens)
            if parent is None:
                raise PatchError("Cannot remove root")
            if key == "-":
                raise PatchError("'-' cannot be used for remove")
            if isinstance(parent, dict):
                if key not in parent:
                    raise PatchError(f"Key {key!r} not found for remove")
                del parent[key]
            elif isinstance(parent, list):
                if not isinstance(key, int) or key < 0 or key >= len(parent):
                    raise PatchError(f"Index {key} out of bounds for remove")
                del parent[key]
            else:
                raise PatchError("Parent is not a container")

        elif op == "replace":
            if not path_tokens:
                result = copy.deepcopy(value)
                continue
            parent, key = _get_parent_and_target(result, path_tokens)
            if parent is None:
                raise PatchError("Cannot replace root")
            if key == "-":
                raise PatchError("'-' cannot be used for replace")
            if isinstance(parent, dict):
                if key not in parent:
                    raise PatchError(f"Key {key!r} not found for replace")
                parent[key] = copy.deepcopy(value)
            elif isinstance(parent, list):
                if not isinstance(key, int) or key < 0 or key >= len(parent):
                    raise PatchError(f"Index {key} out of bounds for replace")
                parent[key] = copy.deepcopy(value)
            else:
                raise PatchError("Parent is not a container")

        elif op == "move":
            if not from_tokens:
                raise PatchError("Cannot move root document")
            if not path_tokens:
                raise PatchError("Cannot move to root document")

            # Check if path is strictly inside from
            if len(path_tokens) < len(from_tokens):
                raise PatchError("Cannot move to ancestor")
            if path_tokens[:len(from_tokens)] != from_tokens:
                raise PatchError("Cannot move to ancestor")
            if path_tokens == from_tokens:
